/**
 * ritorna la distanza fra due punti
 */
function distance(x1, y1, x2, y2) {
    return Math.sqrt( Math.pow(x2 - x1,2) + Math.pow(y2 - y1, 2 ));
}

/**
 * slot delle etichette intorno al pallino (N, S, E, W, NE, NW, SE, SW)
 */
function SlotEtichetteIntorno() {
    const d = 1;
    return [
        { textAlign: 'center', textBaseline: 'bottom', offsetX: 0,  offsetY: -d },
        { textAlign: 'center', textBaseline: 'top',    offsetX: 0,  offsetY:  d },
        { textAlign: 'left',   textBaseline: 'middle', offsetX:  d, offsetY:  0 },
        { textAlign: 'right',  textBaseline: 'middle', offsetX: -d, offsetY:  0 },
        { textAlign: 'left',   textBaseline: 'bottom', offsetX:  d, offsetY: -d },
        { textAlign: 'right',  textBaseline: 'bottom', offsetX: -d, offsetY: -d },
        { textAlign: 'left',   textBaseline: 'top',    offsetX:  d, offsetY:  d },
        { textAlign: 'right',  textBaseline: 'top',    offsetX: -d, offsetY:  d }
    ];
}

/**
 * per ogni stazione sceglie la posizione dell'etichetta intorno al pallino.
 * Isolata: nord (come i pallini singoli). Vicini: nord+sud, poi est, ovest e diagonali.
 */
function CalcolaPosizioniEtichette(stzData) {
    const n = stzData.length;
    const slotIntorno = SlotEtichetteIntorno();
    const slotNord = slotIntorno[0];
    const posiz = new Array(n);
    const vicini = [];

    for (let i = 0; i < n; i++) {
        vicini[i] = [];
        for (let j = 0; j < n; j++) {
            if (i === j) {
                continue;
            }
            if (distance(stzData[i].longitudine, stzData[i].latitudine,
                         stzData[j].longitudine, stzData[j].latitudine) < DISTANZA_STAZ) {
                vicini[i].push(j);
            }
        }
    }

    const visto = new Array(n).fill(false);
    for (let i = 0; i < n; i++) {
        if (visto[i]) {
            continue;
        }

        const gruppo = [];
        const coda = [i];
        visto[i] = true;
        while (coda.length > 0) {
            const k = coda.shift();
            gruppo.push(k);
            vicini[k].forEach(j => {
                if (!visto[j]) {
                    visto[j] = true;
                    coda.push(j);
                }
            });
        }

        if (gruppo.length === 1) {
            posiz[gruppo[0]] = slotNord;
        } else {
            gruppo.forEach((idx, ordine) => {
                posiz[idx] = slotIntorno[ordine % slotIntorno.length];
            });
        }
    }

    return posiz;
