/**
 * download CSV del contenuto visualizzato in meteoTabella (separatore ';' per Excel)
 * Esporta titoli, tutte le tabelle (13 colonne giorno+mesi, 31 righe) e le note.
 */
function downloadCsvMeteoTabella(nomeFile) {
    const contenitore = document.getElementById('contenutoMeteoTabella')
        || document.getElementById('meteoTabella');
    if (!contenitore) { return; }

    const separatore = ';';
    const escapeCsv = function (valore) {
        const testo = (valore || '').replace(/\s+/g, ' ').trim();
        if (testo.indexOf('"') >= 0 || testo.indexOf(separatore) >= 0 || testo.indexOf('\n') >= 0) {
            return '"' + testo.replaceAll('"', '""') + '"';
        }
        return testo;
    };

    const righeCsv = [];
    let buffer = '';

    const flushBuffer = function () {
        const testo = buffer.replace(/\s+/g, ' ').trim();
        if (testo) {
            righeCsv.push(escapeCsv(testo));
        }
        buffer = '';
    };

    const tabellaToCsv = function (tabella) {
        tabella.querySelectorAll('tr').forEach((riga) => {
            const celleCsv = [];
            riga.querySelectorAll('th,td').forEach((cella) => {
                const colspan = parseInt(cella.getAttribute('colspan') || '1', 10);
                const valore = escapeCsv(cella.innerText);
                for (let i = 0; i < colspan; i++) {
                    celleCsv.push(valore);
                }
            });
            righeCsv.push(celleCsv.join(separatore));
        });
    };

    const visit = function (node) {
        if (node.nodeType === 3) {
            buffer += node.textContent;
            return;
        }
        if (node.nodeType !== 1) {
            return;
        }
        const tag = node.tagName;
        if (tag === 'TABLE') {
            flushBuffer();
            tabellaToCsv(node);
            righeCsv.push('');
            return;
        }
        if (tag === 'HR') {
            flushBuffer();
            righeCsv.push('');
            return;
        }
        if (tag === 'BR') {
            flushBuffer();
            return;
        }
        if (tag === 'A') {
            return;
        }
        node.childNodes.forEach(visit);
    };

    visit(contenitore);
    flushBuffer();

    const csv = '\uFEFF' + righeCsv.join('\r\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = nomeFile;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

