/**
 * Visualizzo la tabella delle stazioni
 */
function TabellaStazioni() {

    document.getElementById('meteoTabella').innerHTML = 'Caricamento dati<br><br>';
    document.getElementById('meteoMap').scrollIntoView();

    // metto le stazioni in ordine alfabetico per provincia (sono già in ordine alfabetico basta dividerle per provincia)
    let ord = {'BELLUNO' : [], 'PADOVA' : [], 'ROVIGO' : [], 'TREVISO' : [], 'VENEZIA' : [], 'VICENZA' : [], 'VERONA' : [], 'UDINE' : []};

    jsonStazioni.forEach((stazione, index) => {            
        ord[ stazione.provincia ].push( stazione );
    });
    // myConsoleLog( JSON.stringify(ord, null, 4) );

    var table = document.createElement('table');
    table.setAttribute('id', 'eleStazioni');
    table.setAttribute('class', 'table table-sm table-striped table-bordered table-hover');
    var body = table.createTBody();

    // ciclo le province
    Object.keys(ord).forEach( nomeProv => {       

        var rowProv = body.insertRow(-1);
        var cellProv = rowProv.insertCell(-1);
        cellProv.colSpan = '2';
        cellProv.innerHTML = 'Stazioni con il sensore ' + currentBtn.pulsante + 
        ' nella provincia di ' + titleCase(nomeProv) + " nell'anno " + currentAnno;

        cellProv.style.textAlign = "center";
        cellProv.style.backgroundColor = btnBackgroundColor;

        // ciclo le stazioni della provincia
        for (let index = 0; index < ord[nomeProv].length; index += 2) {
            const e1 = ord[nomeProv][index];
            const e2 = ord[nomeProv][index+1];

            var row = body.insertRow(-1);
            const cell1 = row.insertCell(-1);
            const cell2 = row.insertCell(-1);
            cell1.innerHTML = e1.nome_stazione + ' (' + e1.codice_stazione + ')';
            cell1.onclick = function () { vediDati( e1 ); }
            cell1.onmouseover  = function () {  cell1.style.cursor = "pointer"; }
            cell1.onmouseout  = function () {  cell1.style.cursor = "default"; }

            if (e2) {
                cell2.innerHTML = e2.nome_stazione + ' (' + e2.codice_stazione + ')';
                cell2.onclick = function () { vediDati( e2 ); }
                cell2.onmouseover  = function () { cell2.style.cursor = "pointer"; }
                cell2.onmouseout  = function () { cell2.style.cursor = "default"; }
            } else {
                cell2.innerHTML = '';
            }
        }
    });
    var divTab = document.createElement('div');
    divTab.setAttribute('id', 'tabElencoStazioni');
    divTab.setAttribute('class', 'bmodal-body');
    divTab.style.height = "500px";
    divTab.style.overflowY = "scroll";
    divTab.append(table);

    document.getElementById('meteoTabella').innerHTML = '';
    document.getElementById('meteoTabella').append(divTab);

    var tagBR = document.createElement('br');
    document.getElementById('meteoTabella').append(tagBR);
    document.getElementById('meteoTabella').append(tagBR);

    document.getElementById('meteoTabella').style.border = "";

}


/**
 * Generates HTML
 */
function generateHTML() {

    // elementi della pagina
    CreaDiv();

    // l'anno corrente è presente nel db alla sera del 25 febbraio
    // in quanto i dati vengono aggiornati al 25 del mese con il mese precedente
    const today = new Date();
    currentAnno = today.getFullYear();
    const mm = today.getMonth() + 1; // Months start at 0!
    const dd = today.getDate();
    if ( ( mm <= 2 ) && ( dd <= 25) ) {
        currentAnno -= 1;
    }

    // metto l'anno giusto
    document.getElementById('annoCorrente').innerHTML = 'Anno ' + currentAnno + ' ';
    document.getElementById('annoCorrente').append( AggiungiDown() );

    // parto dal pulsante della temperatura
    document.getElementById('btnTEMP').click();

}


generateHTML();
